function sanitize(body) {
  const clean = {};
  for (const [key, value] of Object.entries(body || {})) {
    if (/^MediaUrl\d+$/i.test(key) || /^MediaUrl$/i.test(key)) continue;
    clean[key] = value;
  }
  return clean;
}

const webhook = $input.first().json || {};
const body = webhook.body || webhook || {};
const rawBody = String(body.Body || '').trim();
const buttonPayload = String(body.ButtonPayload || '').trim();
const buttonText = String(body.ButtonText || '').trim();
const listId = String(body.ListId || body.ListID || '').trim();
const listTitle = String(body.ListTitle || '').trim();
const bodyForIntent = String(buttonPayload || buttonText || listId || listTitle || rawBody || '').trim();
const numMedia = parseInt(String(body.NumMedia || 0), 10) || 0;
const mediaContentTypes = [];
const mediaUrls = [];
for (let i = 0; i < numMedia; i++) {
  if (body[`MediaContentType${i}`]) mediaContentTypes.push(String(body[`MediaContentType${i}`]));
  if (body[`MediaUrl${i}`]) mediaUrls.push(String(body[`MediaUrl${i}`]));
}

return [{
  json: {
    from: String(body.From || ''),
    to: String(body.To || ''),
    body: bodyForIntent,
    messageSid: String(body.MessageSid || body.SmsMessageSid || body.SmsSid || '').trim() || null,
    profileName: String(body.ProfileName || '').trim() || null,
    numMedia,
    mediaContentTypes,
    mediaUrls,
    rawPayload: sanitize(body)
  }
}];

let inbound = {};
try {
  inbound = $('Preparar inbound Twilio').item.json || {};
} catch (error) {
  inbound = $input.first().json || {};
}

const gemini = $input.first().json || {};
const classification = {
  intent_key: typeof gemini.intent_key === 'string' ? gemini.intent_key : undefined,
  confidence: Number(gemini.confidence || 0),
  needs_operator: Boolean(gemini.needs_operator),
  reason: typeof gemini.reason === 'string' ? gemini.reason : undefined
};

return [{
  json: {
    ...inbound,
    geminiClassification: classification
  }
}];
